package app.dayflow.markdown;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.BitmapDrawable;import android.net.Uri;import android.util.*;import io.noties.markwon.image.*;import java.util.*;import java.io.*;import java.net.*;
/** Stream compressed images to private temporary files, then sample decode. Never attach credentials. */
final class NoteImages extends SchemeHandler {
 private final Context context;private static final LruCache<String,Bitmap> cache=new LruCache<>(8*1024*1024){protected int sizeOf(String key,Bitmap bitmap){return bitmap.getAllocationByteCount()+256;}};
 NoteImages(Context c){context=c.getApplicationContext();}public Collection<String> supportedSchemes(){return Arrays.asList("data","https","http","content","file");}
 public ImageItem handle(String raw,Uri uri){File temp=null;try{String key=android.util.Base64.encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8)),android.util.Base64.NO_WRAP);Bitmap bitmap=cache.get(key);if(bitmap==null){File folder=new File(context.getCacheDir(),"image-input");folder.mkdirs();temp=File.createTempFile("image-",".bin",folder);if(uri.getScheme().equals("https")||uri.getScheme().equals("http"))download(new URL(Network.endpoint(raw,true)),temp);else if(uri.getScheme().equals("data")){int split=raw.indexOf(',');if(split<0)throw new IOException("无效图片数据");if(raw.substring(0,split).contains(";base64")){final int start=split+1;InputStream ascii=new InputStream(){int at=start;public int read(){return at<raw.length()?raw.charAt(at++):-1;}public int read(byte[] bytes,int offset,int length){if(at>=raw.length())return -1;int count=Math.min(length,raw.length()-at);for(int i=0;i<count;i++)bytes[offset+i]=(byte)raw.charAt(at++);return count;}};try(InputStream input=new Base64InputStream(ascii,android.util.Base64.DEFAULT)){copy(input,temp);}}else try(InputStream input=new ByteArrayInputStream(Uri.decode(raw.substring(split+1)).getBytes(java.nio.charset.StandardCharsets.UTF_8))){copy(input,temp);}}else try(InputStream input=context.getContentResolver().openInputStream(uri)){copy(input,temp);}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getPath(),options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("不支持的图片格式");options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1400||(long)options.outWidth*options.outHeight/options.inSampleSize/options.inSampleSize>2000000)options.inSampleSize*=2;options.inJustDecodeBounds=false;bitmap=BitmapFactory.decodeFile(temp.getPath(),options);if(bitmap==null)throw new IOException("图片解码失败");cache.put(key,bitmap);}BitmapDrawable drawable=new BitmapDrawable(context.getResources(),bitmap);drawable.setBounds(0,0,bitmap.getWidth(),bitmap.getHeight());return ImageItem.withResult(drawable);}catch(Exception e){throw new IllegalArgumentException("图片未加载："+e.getMessage(),e);}finally{if(temp!=null)temp.delete();}}
 private static void copy(InputStream in,File file)throws IOException{if(in==null)throw new IOException("无法读取图片");try(OutputStream out=new FileOutputStream(file)){byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("图片加载已取消");out.write(buffer,0,count);}}}
 private void download(URL url,File file)throws Exception{for(int redirects=0;redirects<4;redirects++){HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(15000);connection.setInstanceFollowRedirects(false);try{int status=connection.getResponseCode();if(status>=300&&status<400){URL next=new URL(url,connection.getHeaderField("Location"));Network.endpoint(next.toString(),true);if(!next.getProtocol().equals("https"))throw new IOException("图片重定向需HTTPS");url=next;continue;}if(status!=200)throw new IOException("图片HTTP "+status);try(InputStream in=connection.getInputStream()){copy(in,file);return;}}finally{connection.disconnect();}}throw new IOException("图片重定向过多");}
 static void clearCache(){cache.evictAll();}
}
